target.query:
// Past events System 1 labelled in batch (p4n4 ai system1 label --write), for the selected set
from(bucket: "ai_events")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "system1_label" and r.set == "${set}" and r._field == "subject")
  |> map(fn: (r) => ({_time: r._time, text: r.question + ": " + r.choice + (if r._value != "" then " (" + r._value + ")" else ""), tags: r.set}))
  |> group()

targets.query:
// Each option's share of the answers, and the abstention rate, in the last 7
// days against the 28 days before (docs: decisions/system1.md §10.4). A move of
// more than 20 points, or a doubled abstention rate, means: evaluate again.
share = (start, stop, period) => {
  rows = from(bucket: "ai_events")
    |> range(start: start, stop: stop)
    |> filter(fn: (r) => r._measurement == "system1_decision" and r.set == "${set}" and r.question == "${question}" and r._field == "abstain")
    |> map(fn: (r) => ({key: 1, choice: if r._value then "(abstained)" else r.choice, n: 1.0}))
    |> group()
  per = rows |> group(columns: ["key", "choice"]) |> sum(column: "n") |> group()
  all = rows |> group(columns: ["key"]) |> sum(column: "n") |> rename(columns: {n: "total"}) |> group()
  return join(tables: {a: per, b: all}, on: ["key"])
    |> map(fn: (r) => ({choice: r.choice, period: period, share: 100.0 * r.n / r.total}))
}
union(tables: [
  share(start: -7d, stop: now(), period: "Last 7 days (%)"),
  share(start: -35d, stop: -7d, period: "28 days before (%)"),
])
  |> group()
  |> pivot(rowKey: ["choice"], columnKey: ["period"], valueColumn: "share")
  |> map(fn: (r) => ({r with "Change (points)": if exists r["Last 7 days (%)"] and exists r["28 days before (%)"] then r["Last 7 days (%)"] - r["28 days before (%)"] else if exists r["Last 7 days (%)"] then r["Last 7 days (%)"] else 0.0 - r["28 days before (%)"]}))
  |> sort(columns: ["choice"])
